package com.aistock.scheduler.statistics;
import com.aistock.common.statistics.*;import com.aistock.scheduler.task.TaskRepository;import java.time.*;import java.sql.Timestamp;import java.util.*;import org.flywaydb.core.Flyway;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.util.LinkedMultiValueMap;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class TaskStatisticsMysqlTest {
 static final Instant NOW=Instant.parse("2026-10-22T04:00:00Z"),START=Instant.parse("2026-10-20T00:00:00Z");JdbcTemplate jdbc;TaskRepository tasks;
 @BeforeEach void init(){String url=System.getenv("SCHEDULER_TEST_DB_URL"),secret=System.getenv("SCHEDULER_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_scheduler_test?serverTimezone=UTC".equals(url)||secret==null||secret.isBlank())throw new IllegalStateException("Only isolated test DB allowed");var ds=new DriverManagerDataSource(url,"root",secret);ds.setDriverClassName("com.mysql.cj.jdbc.Driver");Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();jdbc=new JdbcTemplate(ds);assertEquals("stock_scheduler_test",jdbc.queryForObject("select database()",String.class));for(var t:List.of("admin_market_refresh_operation","admin_market_refresh_guard","admin_market_refresh_context","admin_task_operation","comparison_update_context","task_attempt","scheduled_task"))jdbc.update("delete from "+t);tasks=new TaskRepository(jdbc);}
 static StatisticsWindow window(){var q=new LinkedMultiValueMap<String,String>();q.add("from","2026-10-20");q.add("to","2026-10-22");return StatisticsWindow.parse(q,Clock.fixed(NOW,ZoneOffset.UTC));}
 String task(Instant created){return tasks.create("SH600030",created.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate(),UUID.randomUUID().toString(),created).taskId();}
 void attempt(String id,int n,String state,Instant start,Long duration){jdbc.update("insert into task_attempt(attempt_id,task_id,ordinal,state,started_at,lease_until,finished_at) values(?,?,?,?,?,?,?)",UUID.randomUUID().toString(),id,n,state,Timestamp.from(start),Timestamp.from(start.plusSeconds(120)),duration==null?null:Timestamp.from(start.plusMillis(duration)));}
 @Test void retriesKeepTaskCountAndExcludeNegativeOrUnfinishedDurations(){var id=task(START);attempt(id,1,"SUCCEEDED",START.plusMillis(50),0L);attempt(id,2,"FAILED",START.plusSeconds(60),100L);attempt(id,3,"SUCCEEDED",START.plusSeconds(120),300L);attempt(id,4,"FAILED",START.plusSeconds(180),-1L);attempt(id,5,"RUNNING",START.plusSeconds(240),null);jdbc.update("update scheduled_task set state='RUNNING' where task_id=?",id);var before=jdbc.queryForList("select * from task_attempt order by ordinal");var v=new TaskStatisticsRepository(jdbc).summary(window(),NOW);assertEquals("1",v.taskTotal());assertEquals("5",v.attemptTotal());assertEquals("3",v.attemptDuration().sampleCount());assertEquals("1",v.attemptDuration().excludedInvalidCount());assertEquals("133.333",v.attemptDuration().meanMs());assertEquals("1",v.unfinishedAttempts());assertEquals("50.000",v.firstQueueWait().meanMs());assertEquals("0",jdbc.queryForObject("select revision from scheduled_task where task_id=?",String.class,id));assertEquals(before,jdbc.queryForList("select * from task_attempt order by ordinal"));}
 @Test void attemptWindowDoesNotDependOnParentCreationWindow(){var id=task(Instant.parse("2026-10-01T00:00:00Z"));attempt(id,1,"FAILED",START,200L);var v=new TaskStatisticsRepository(jdbc).summary(window(),NOW);assertEquals("0",v.taskTotal());assertEquals("1",v.attemptTotal());assertEquals("200.000",v.attemptDuration().meanMs());}
 @Test void allTaskStatesRemainSeparateAndEmptyMeansNull(){for(var state:List.of("QUEUED","RUNNING","RECONCILING","RETRY_WAIT","SUCCEEDED","EMPTY","SKIPPED","FAILED","CANCELLED")){var id=task(START);jdbc.update("update scheduled_task set state=? where task_id=?",state,id);}var v=new TaskStatisticsRepository(jdbc).summary(window(),NOW);assertEquals("9",v.taskTotal());assertEquals(9,v.taskStateCounts().size());assertTrue(v.taskStateCounts().stream().allMatch(x->x.count().equals("1")));assertNull(v.attemptDuration().meanMs());assertEquals("0",v.attemptDuration().sampleCount());}
}
